// ── solo ──────────────────────────────────────────────────────────────────────

export const useSolo = (slug: string, issueFilter?: string) =>
  useQuery<SoloItem[]>({
    queryKey: ['solo', slug, issueFilter],
    queryFn: () => {
      const params = new URLSearchParams({ slug })
      if (issueFilter) params.set('issue', issueFilter)
      return apiFetch(`/api/dx/solo?${params}`)
    },
    enabled: !!slug,
  })
